class HomeScreen extends ConsumerStatefulWidget { const HomeScreen({super.key}); @override ConsumerState<HomeScreen> createState() => _HomeScreenState(); }
class _HomeScreenState extends ConsumerState<HomeScreen> {
  String query = ''; GameCategory? category;
  @override Widget build(BuildContext context) { final strings = AppStrings(Localizations.localeOf(context)); final user = ref.watch(authProvider).value?.user; final games = ref.watch(gamesProvider).value ?? localGameCatalog; final filtered = games.where((game) => (category == null || game.category == category) && (query.isEmpty || game.name.toLowerCase().contains(query.toLowerCase()))).toList(); return RefreshIndicator(onRefresh: () async => ref.invalidate(gamesProvider), child: CustomScrollView(slivers: [SliverPadding(padding: const EdgeInsets.fromLTRB(20, 18, 20, 0), sliver: SliverToBoxAdapter(child: _Header(user: user))), SliverPadding(padding: const EdgeInsets.fromLTRB(20, 24, 20, 0), sliver: SliverToBoxAdapter(child: _HeroBanner(onTap: () => _open(context, games.first)))), SliverPadding(padding: const EdgeInsets.fromLTRB(20, 26, 20, 12), sliver: SliverToBoxAdapter(child: Text(strings.games, style: Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight: FontWeight.w900)))), SliverToBoxAdapter(child: SizedBox(height: 42, child: ListView(scrollDirection: Axis.horizontal, padding: const EdgeInsets.symmetric(horizontal: 20), children: [ _FilterChip(label: strings.isPersian ? 'همه' : 'All', active: category == null, onTap: () => setState(() => category = null)), ...GameCategory.values.map((value) => _FilterChip(label: _categoryName(value, strings), active: category == value, onTap: () => setState(() => category = value))), ]))), SliverPadding(padding: const EdgeInsets.fromLTRB(20, 14, 20, 30), sliver: SliverToBoxAdapter(child: TextField(onChanged: (value) => setState(() => query = value), decoration: InputDecoration(hintText: strings.isPersian ? 'جست‌وجوی بازی' : 'Search games', prefixIcon: const Icon(Icons.search_rounded), suffixIcon: query.isEmpty ? null : IconButton(onPressed: () { setState(() => query = ''); }, icon: const Icon(Icons.close_rounded)))))), SliverPadding(padding: const EdgeInsets.symmetric(horizontal: 20), sliver: SliverGrid(delegate: SliverChildBuilderDelegate((context, index) { final game = filtered[index]; return _GameCard(game: game, onTap: () => _open(context, game)); }, childCount: filtered.length), gridDelegate: const SliverGridDelegateWithMaxCrossAxisExtent(maxCrossAxisExtent: 250, mainAxisExtent: 190, crossAxisSpacing: 14, mainAxisSpacing: 14))), if (filtered.isEmpty) SliverFillRemaining(hasScrollBody: false, child: Center(child: Text(strings.isPersian ? 'بازی‌ای پیدا نشد.' : 'No games found.'))), ])); }
  void _open(BuildContext context, GameDescriptor game) => Navigator.of(context).push(MaterialPageRoute(builder: (_) => MatchSetupScreen(game: game)));
  String _categoryName(GameCategory value, AppStrings strings) => switch (value) { GameCategory.board => strings.isPersian ? 'بردی' : 'Board', GameCategory.cards => strings.isPersian ? 'کارتی' : 'Cards', GameCategory.arcade => strings.isPersian ? 'آرکید' : 'Arcade', GameCategory.party => strings.isPersian ? 'دورهمی' : 'Party', GameCategory.sports => strings.isPersian ? 'ورزشی' : 'Sports' };
}

