}

class _FilterChip extends StatelessWidget { const _FilterChip({required this.label, required this.active, required this.onTap}); final String label; final bool active; final VoidCallback onTap; @override Widget build(BuildContext context) => Padding(padding: const EdgeInsetsDirectional.only(end: 8), child: ChoiceChip(label: Text(label), selected: active, onSelected: (_) => onTap(), showCheckmark: false, padding: const EdgeInsets.symmetric(horizontal: 12), labelStyle: TextStyle(fontWeight: FontWeight.w700, color: active ? Colors.white : Theme.of(context).colorScheme.onSurfaceVariant), selectedColor: AppTheme.violet, backgroundColor: Theme.of(context).colorScheme.surface)); }

class _GameCard extends StatelessWidget { const _GameCard({required this.game, required this.onTap}); final GameDescriptor game; final VoidCallback onTap; @override Widget build(BuildContext context) => InkWell(onTap: onTap, borderRadius: BorderRadius.circular(24), child: Card(child: Padding(padding: const EdgeInsets.all(15), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [GameLogo(gameId: game.id, accent: game.accent, size: 54), const Spacer(), Text(game.name, maxLines: 1, overflow: TextOverflow.ellipsis, style: const TextStyle(fontWeight: FontWeight.w900, fontSize: 16)), const SizedBox(height: 4), Row(children: [Icon(Icons.people_alt_outlined, size: 14, color: Theme.of(context).colorScheme.onSurfaceVariant), const SizedBox(width: 4), Text('${game.minPlayers}-${game.maxPlayers}', style: TextStyle(fontSize: 12, color: Theme.of(context).colorScheme.onSurfaceVariant)), const Spacer(), Icon(Icons.arrow_forward_rounded, size: 17, color: Theme.of(context).colorScheme.primary)])]))));
